<script setup>
import { computed,onMounted,ref,watch } from 'vue';import { UiButton,UiPanel,UiSearchSelect,UiPeriodPicker } from '@irlix/ui';import { api } from '../api';import { statusLabels,typeLabels } from '../constants';import AbsenceCreateModal from '../components/AbsenceCreateModal.vue';import AbsenceTable from '../components/AbsenceTable.vue';
const props=defineProps({departments:{type:Array,default:()=>[]},employees:{type:Array,default:()=>[]},canCreateForEmployee:{type:Boolean,default:false},refreshToken:{type:Number,default:0}});const emit=defineEmits(['action','error','changed']);const year=ref(new Date().getFullYear()),items=ref([]),loading=ref(false),search=ref(''),statuses=ref([]),departmentId=ref(''),type=ref(''),activeMonth=ref(null),onlyMyActions=ref(false),showCreate=ref(false);const yearRange=computed(()=>({from:`${year.value}-01-01`,to:`${year.value}-12-31`}));const statusOptions=computed(()=>Object.entries(statusLabels).filter(([value])=>value!=='planned').map(([value,label])=>({value,label})));const departmentOptions=computed(()=>props.departments.map(d=>({value:d.id,label:d.name})));const typeOptions=computed(()=>Object.entries(typeLabels).map(([value,label])=>({value,label})));const departmentEmployeeIds=computed(()=>{const needle=search.value.trim().toLowerCase();return new Set(props.employees.filter(e=>!departmentId.value||String(e.department_id??'')===String(departmentId.value)).filter(e=>!needle||[e.full_name,e.department_name,e.position].filter(Boolean).some(v=>String(v).toLowerCase().includes(needle))).map(e=>Number(e.id)))});const baseFiltered=computed(()=>items.value.filter(item=>departmentEmployeeIds.value.has(Number(item.employee_id))&&(!statuses.value.length||statuses.value.includes(item.status))&&(!type.value||item.type===type.value)));const monthBounds=(monthIndex)=>{const mm=String(monthIndex).padStart(2,'0');const last=new Date(year.value,monthIndex,0).getDate();return{from:`${year.value}-${mm}-01`,to:`${year.value}-${mm}-${String(last).padStart(2,'0')}`}};const overlaps=(item,from,to)=>item.starts_on<=to&&(!item.ends_on||item.ends_on>=from);const parseDate=(value)=>{const[y,m,d]=String(value).slice(0,10).split('-').map(Number);return new Date(Date.UTC(y,m-1,d))};const workingDaysBetween=(from,to)=>{let cursor=parseDate(from),end=parseDate(to),count=0;while(cursor<=end){const day=cursor.getUTCDay();if(day!==0&&day!==6)count++;cursor=new Date(cursor.getTime()+86400000)}return count};const absenceHoursInMonth=(item,monthIndex)=>{if(['rejected','cancelled'].includes(item.status))return 0;const b=monthBounds(monthIndex);if(!overlaps(item,b.from,b.to))return 0;const from=item.starts_on>b.from?item.starts_on:b.from;const endValue=item.ends_on||b.to;const to=endValue<b.to?endValue:b.to;return workingDaysBetween(from,to)*8};const workingDaysInMonth=(monthIndex)=>{const b=monthBounds(monthIndex);return workingDaysBetween(b.from,b.to)};const monthCards=computed(()=>Array.from({length:12},(_,index)=>{const month=index+1,totalHours=departmentEmployeeIds.value.size*workingDaysInMonth(month)*8,absenceHours=baseFiltered.value.reduce((sum,item)=>sum+absenceHoursInMonth(item,month),0);return{month,label:`${String(month).padStart(2,'0')}.${year.value}`,absenceHours,totalHours,percent:totalHours>0?Math.round(absenceHours/totalHours*100):0}}));const filteredItems=computed(()=>{let result=baseFiltered.value;if(activeMonth.value){const b=monthBounds(activeMonth.value);result=result.filter(item=>overlaps(item,b.from,b.to))}if(onlyMyActions.value)result=result.filter(item=>Boolean(item.requires_my_action));return result});const myActionCount=computed(()=>baseFiltered.value.filter(item=>item.requires_my_action).length);const load=async()=>{loading.value=true;try{const params=new URLSearchParams({from:yearRange.value.from,to:yearRange.value.to});const payload=await api(`/api/vacations/registry?${params}`);items.value=payload.data||[]}catch(error){emit('error',error.message)}finally{loading.value=false}};const selectMonth=(month)=>{activeMonth.value=activeMonth.value===month?null:month};const clearFilters=()=>{search.value='';statuses.value=[];departmentId.value='';type.value='';activeMonth.value=null;onlyMyActions.value=false};const created=async()=>{showCreate.value=false;await load();emit('changed')};onMounted(load);watch(()=>props.refreshToken,load);watch(year,()=>{activeMonth.value=null;load()});
</script><template><Teleport to="#vacations-topbar-actions"><div class="vacations-topbar-controls vacations-topbar-controls--manage"><input v-model="search" class="topbar-search" type="search" placeholder="Поиск"/><UiSearchSelect v-model="statuses" class="topbar-select" :options="statusOptions" placeholder="Статусы" multiple/><UiSearchSelect v-model="departmentId" class="topbar-select" :options="departmentOptions" placeholder="Подразделение"/><UiSearchSelect v-model="type" class="topbar-select" :options="typeOptions" placeholder="Тип"/><UiPeriodPicker v-model="year" mode="year"/><button type="button" class="my-actions-filter compact" :class="{active:onlyMyActions}" @click="onlyMyActions=!onlyMyActions">Мои действия <span>{{ myActionCount }}</span></button><button type="button" class="reset-filter" @click="clearFilters">Сбросить</button><UiButton v-if="canCreateForEmployee" compact @click="showCreate=true">+ Создать отсутствие</UiButton></div></Teleport><UiPanel class="manage-panel"><div class="month-cards" aria-label="Быстрый фильтр по месяцам"><button v-for="card in monthCards" :key="card.month" type="button" class="month-card" :class="{active:activeMonth===card.month}" @click="selectMonth(card.month)"><span>{{ card.label }}</span><strong>{{ card.percent }}%</strong><small><b>Отсутствия:</b><em>{{ card.absenceHours }}ч</em></small><small><b>Всего:</b><em>{{ card.totalHours }}ч</em></small></button></div><div class="registry-meta"><span>Найдено: <strong>{{ filteredItems.length }}</strong></span><span v-if="activeMonth">Быстрый фильтр: <strong>{{ String(activeMonth).padStart(2,'0') }}.{{ year }}</strong></span></div><div v-if="loading" class="empty">Загрузка реестра…</div><div v-else-if="!filteredItems.length" class="empty"><strong>Ничего не найдено</strong><span>Измените фильтры или выберите другой месяц.</span></div><AbsenceTable v-else :items="filteredItems" :show-documents="false" :hidden-actions="['view','history','view_attachments']" show-employee show-progress @action="emit('action',$event)"/></UiPanel><AbsenceCreateModal :open="showCreate" :employees="employees" for-employee title="Создать отсутствие сотруднику" eyebrow="НОВОЕ ОТСУТСТВИЕ" @close="showCreate=false" @changed="created"/></template>
